/**
 * The breadcrumbs of an inner page: links to the parent pages separated by chevrons; the last entry is the
 * current page and is not a link.
 */
import { For, type JSX } from "solid-js";
import { Block } from "../primitives/block/block";
import { Inline } from "../primitives/inline/inline";
import { Link } from "../primitives/link/link";
import { List } from "../primitives/list/list";
import { ListItem } from "../primitives/list/list-item";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import type { NavLink } from "../blocks/nav-bar.types";

export type PageCrumbsProps = {
  label: string;
  crumbs: NavLink[];
  landmarkLabel?: string;
};

export function PageCrumbs({ label, crumbs, landmarkLabel }: PageCrumbsProps) {
  const last = (crumbs?.length ?? 0) - 1;
  return (
    <Block tag="nav" aria-label={(landmarkLabel ?? label)} data-testid="crumbs">
      <List class="m-0 flex list-none flex-wrap items-center gap-2 p-0 text-sm text-muted-foreground">
        <For each={crumbs ?? []}>{(c, iOf) => { const i = iOf(); return (
          <ListItem class="flex items-center gap-2">
            {(i < last) ? (
              <>
                <Link href="#/" variant="muted" size="sm" data-testid="crumb">
                  {c.name}
                </Link>
                <LucideIcon name="chevron-right" size={16} />
              </>
            ) : (
              <Inline class="font-medium text-foreground" aria-current="page">
                {c.name}
              </Inline>
            )}
          </ListItem>
        ); }}</For>
      </List>
    </Block>
  );
}
